    if (!nullToAbsent || actualCountPiasters != null) {
      map['actual_count_piasters'] = Variable<int>(actualCountPiasters);
    }
    if (!nullToAbsent || closedAt != null) {
      map['closed_at'] = Variable<DateTime>(closedAt);
    }
    if (!nullToAbsent || notes != null) {
